#!/usr/bin/env node
// Captures the REAL compiled output of this repo's emitters into
// website/src/data/emitter-output.js.
//
// Contract (T003 §4):
//   * reads twelve committed files with fs — never imports @frameless/compiler
//   * verbatim: no reformatting, no re-indentation (the files use tabs), no
//     truncation, no ellipsis. The only normalization is \r\n -> \n.
//   * provenance gate: every captured output's first line must be exactly
//     "// @generated by @frameless/<framework>; do not edit." or we exit 1.
//   * deterministic: no timestamp. Same inputs -> byte-identical artifact.
//
// Deviation from the letter of T003 §4, recorded deliberately:
//   §4's sketch shows `commit: "<git rev-parse HEAD>"`. Using HEAD makes the
//   artifact non-deterministic across *unrelated* commits, which would make the
//   contract's own `git diff --quiet website/src/data/emitter-output.js` verify
//   step fail permanently the moment anything else in the repo is committed.
//   We record instead the last commit that touched the twelve captured inputs
//   plus a `dirty` flag. That is strictly more truthful provenance (it answers
//   "which commit is this output traceable to?") and it is stable, so the
//   determinism check stays meaningful.

import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const websiteRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const repoRoot = resolve(websiteRoot, '..');

const FRAMEWORKS = ['react', 'solid', 'qwik'];

const SCENARIOS = [
	{
		id: 's1',
		file: 'S1',
		title: 'RenderOnce',
		fixture: 'packages/compiler/test/fixtures/s1-render-once.tsrx',
		blurb:
			'One source, one conditional branch, one derived value. The cheapest possible proof that the emitters are not doing lowest-common-denominator syntax translation: Solid reaches for <Show when= fallback=>, React and Qwik emit a ternary.',
	},
	{
		id: 's2',
		file: 'S2',
		title: 'KeyedTodo',
		fixture: 'packages/compiler/test/fixtures/s2-keyed-todo.tsrx',
		blurb:
			'A keyed list. Solid emits <For>, React emits array .map, Qwik emits useStore — three genuinely different list strategies from one source.',
	},
	{
		id: 's3',
		file: 'S3',
		title: 'EventForm',
		fixture: 'packages/compiler/test/fixtures/s3-event-form.tsrx',
		blurb: 'Events, controlled input and form state across the three activation models.',
	},
];

// The reactivity/activation facts shown in the panel spec table. Repo-verified,
// not invented: they are read straight off the emitted code and the e2e runner.
const FRAMEWORK_FACTS = {
	react: {
		label: 'React',
		primitive: 'useState / useRef',
		activation: 'Hydrates',
		accent: 'sky',
		lede: 'Hooks, a ternary for the branch, and a plain template literal for the derived value. Nothing clever — which is the point.',
	},
	solid: {
		label: 'Solid',
		primitive: 'createSignal',
		activation: 'Hydrates',
		accent: 'cliff',
		lede: 'Signals plus <Show when= fallback=>. Solid gets Solid idiom, not translated React.',
	},
	qwik: {
		label: 'Qwik',
		primitive: 'useSignal / useComputed$',
		activation: 'Resumes',
		accent: 'teal',
		lede: 'component$, useTask$ and $-wrapped handlers. Same source, a completely different activation model.',
	},
};

function fail(message) {
	process.stderr.write(`capture-emitter-output: ${message}\n`);
	process.exit(1);
}

function readVerbatim(relativePath) {
	const absolute = join(repoRoot, relativePath);
	if (!existsSync(absolute)) {
		fail(
			`missing input file.\n  expected: ${absolute}\n` +
				`  Refusing to emit a partial artifact or a stub. If the emitters moved, fix the\n` +
				`  path list in this script rather than letting the site ship invented code.`,
		);
	}
	// \r\n -> \n is the ONLY permitted normalization.
	return readFileSync(absolute, 'utf8').replace(/\r\n/g, '\n');
}

function provenanceGate(framework, relativePath, code) {
	const expected = `// @generated by @frameless/${framework}; do not edit.`;
	const firstLine = code.split('\n', 1)[0];
	if (firstLine !== expected) {
		fail(
			`provenance gate failed for ${relativePath}\n` +
				`  expected first line: ${JSON.stringify(expected)}\n` +
				`  actual first line:   ${JSON.stringify(firstLine)}\n` +
				`  This build step refuses to ship anything that did not come out of an emitter.`,
		);
	}
}

function git(args) {
	try {
		return execFileSync('git', args, { cwd: repoRoot, encoding: 'utf8' }).trim();
	} catch {
		return '';
	}
}

function main() {
	const inputPaths = [];
	const scenarios = SCENARIOS.map((scenario) => {
		inputPaths.push(scenario.fixture);
		const source = readVerbatim(scenario.fixture);

		const outputs = {};
		for (const framework of FRAMEWORKS) {
			const relativePath = `packages/frameworks/${framework}/generated/${scenario.file}.jsx`;
			inputPaths.push(relativePath);
			const code = readVerbatim(relativePath);
			provenanceGate(framework, relativePath, code);
			outputs[framework] = {
				framework,
				label: FRAMEWORK_FACTS[framework].label,
				primitive: FRAMEWORK_FACTS[framework].primitive,
				activation: FRAMEWORK_FACTS[framework].activation,
				accent: FRAMEWORK_FACTS[framework].accent,
				lede: FRAMEWORK_FACTS[framework].lede,
				path: relativePath,
				code,
				sha256: createHash('sha256').update(code, 'utf8').digest('hex'),
				lines: code.replace(/\n$/, '').split('\n').length,
				bytes: Buffer.byteLength(code, 'utf8'),
			};
		}

		return {
			id: scenario.id,
			title: scenario.title,
			blurb: scenario.blurb,
			sourcePath: scenario.fixture,
			source,
			sourceLines: source.replace(/\n$/, '').split('\n').length,
			outputs,
		};
	});

	const commit = git(['log', '-1', '--format=%H', '--', ...inputPaths]);
	const dirty = git(['status', '--porcelain', '--', ...inputPaths]) !== '';

	const payload = {
		commit: commit || 'unknown',
		commitScope: 'last commit touching the captured fixture and generated files',
		dirty,
		frameworks: FRAMEWORKS,
		verifiedBy: 'pnpm e2e — 3 frameworks x 3 scenarios, real browser',
		scenarios,
	};

	const artifact =
		'// @generated by website/scripts/capture-emitter-output.mjs — do not edit by hand.\n' +
		'// Every `code` string below is the verbatim contents of a file under\n' +
		'// packages/frameworks/<fw>/generated/. Re-run the script to prove it is current.\n' +
		`export default ${JSON.stringify(payload, null, '\t')};\n`;

	const outputPath = join(websiteRoot, 'src', 'data', 'emitter-output.js');
	mkdirSync(dirname(outputPath), { recursive: true });
	writeFileSync(outputPath, artifact, 'utf8');

	process.stdout.write(`capture-emitter-output: wrote ${outputPath}\n`);
	process.stdout.write(`  commit ${payload.commit}${dirty ? ' (INPUTS DIRTY)' : ''}\n`);
	for (const scenario of scenarios) {
		for (const framework of FRAMEWORKS) {
			const out = scenario.outputs[framework];
			process.stdout.write(
				`  ${scenario.id} ${framework.padEnd(5)} ${String(out.lines).padStart(3)} lines  ${String(out.bytes).padStart(5)} bytes  ${out.sha256.slice(0, 12)}  ${out.path}\n`,
			);
		}
	}
	process.stdout.write('capture-emitter-output: OK — provenance gate passed on 9 files.\n');
}

main();
